6.query:
fetch logs
| filter log.source == "kong-audit-webhook"
| makeTimeseries cnt = count(), interval:1h, by:{konnect_format}

8.query:
fetch logs
| filter log.source == "kong-audit-webhook" and konnect_format == "authentication"
| summarize cnt = count(), by:{audit.status}

9.query:
fetch logs
| filter log.source == "kong-audit-webhook" and konnect_format == "authentication"
| summarize cnt = count(), by:{audit.action}
